AHFLParser::AHFLParser(TokenStream *input) : AHFLParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

AHFLParser::AHFLParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  AHFLParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *ahflParserStaticData->atn, ahflParserStaticData->decisionToDFA, ahflParserStaticData->sharedContextCache, options);
}

AHFLParser::~AHFLParser() {
  delete _interpreter;
}

const atn::ATN& AHFLParser::getATN() const {
  return *ahflParserStaticData->atn;
}

std::string AHFLParser::getGrammarFileName() const {
  return "AHFL.g4";
}

const std::vector<std::string>& AHFLParser::getRuleNames() const {
  return ahflParserStaticData->ruleNames;
}

const dfa::Vocabulary& AHFLParser::getVocabulary() const {
  return ahflParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView AHFLParser::getSerializedATN() const {
  return ahflParserStaticData->serializedATN;
}


//----------------- ProgramContext ------------------------------------------------------------------

AHFLParser::ProgramContext::ProgramContext(ParserRuleContext *parent, size_t invokingState)
  : ParserRuleContext(parent, invokingState) {
}

tree::TerminalNode* AHFLParser::ProgramContext::EOF() {
  return getToken(AHFLParser::EOF, 0);
}

std::vector<AHFLParser::ModuleDeclContext *> AHFLParser::ProgramContext::moduleDecl() {
  return getRuleContexts<AHFLParser::ModuleDeclContext>();
}

AHFLParser::ModuleDeclContext* AHFLParser::ProgramContext::moduleDecl(size_t i) {
  return getRuleContext<AHFLParser::ModuleDeclContext>(i);
}

std::vector<AHFLParser::ImportDeclContext *> AHFLParser::ProgramContext::importDecl() {
  return getRuleContexts<AHFLParser::ImportDeclContext>();
}

AHFLParser::ImportDeclContext* AHFLParser::ProgramContext::importDecl(size_t i) {
  return getRuleContext<AHFLParser::ImportDeclContext>(i);
}

std::vector<AHFLParser::TopLevelDeclContext *> AHFLParser::ProgramContext::topLevelDecl() {
  return getRuleContexts<AHFLParser::TopLevelDeclContext>();
}

AHFLParser::TopLevelDeclContext* AHFLParser::ProgramContext::topLevelDecl(size_t i) {
  return getRuleContext<AHFLParser::TopLevelDeclContext>(i);
}


size_t AHFLParser::ProgramContext::getRuleIndex() const {
  return AHFLParser::RuleProgram;
}


std::any AHFLParser::ProgramContext::accept(tree::ParseTreeVisitor *visitor) {
  if (auto parserVisitor = dynamic_cast<AHFLVisitor*>(visitor))
    return parserVisitor->visitProgram(this);
  else
    return visitor->visitChildren(this);
}

